    Stream* stream = nullptr;
    uint8_t datos[17];
    uint8_t largo = 0, cabecera = 0;
    bool listo = false, tiene_anterior = false;
    float yaw = 0, pitch = 0, roll = 0, ax = 0, ay = 0, az = 0, cero = 0, anterior = 0, acumulado = 0;
